// Code node — extract id, companyId, icpMatch, icpTier, intentScore,
// leadScore, icpScore from each item's AI agent output
const FIELDS = [
  'icpMatch',
  'icpTier',
  'intentScore',
  'icpScore',
  'icpReason',
  'recommendedService'
];

function extractJsonBlock(text) {
  if (typeof text !== 'string') return null;
  const fenceMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/i);
  const candidate = fenceMatch ? fenceMatch[1] : text;
  try {
    return JSON.parse(candidate.trim());
  } catch (e) {
    const braceMatch = text.match(/\{[\s\S]*\}/);
    if (braceMatch) {
      try {
        return JSON.parse(braceMatch[0]);
      } catch (e2) {
        return null;
      }
    }
    return null;
  }
}

function parseToonFields(text) {
  const result = {};
  if (typeof text !== 'string') return result;
  const lines = text.split('\n');
  for (const rawLine of lines) {
    const line = rawLine.replace(/\r$/, '');
    if (!line || /^\s/.test(line)) continue;
    const match = line.match(/^([A-Za-z0-9_]+)\s*:\s*(.*)$/);
    if (!match) continue;
    const [, key, rawValue] = match;
    result[key] = rawValue.trim();
  }
  return result;
}

// Coerces a raw value into the right type for a given field
function coerceValue(field, value) {
  if (value === undefined || value === null || value === '') return null;

  if (field === 'icpMatch') {
    if (typeof value === 'boolean') return value;
    const v = String(value).trim().toLowerCase();
    if (v === 'true') return true;
    if (v === 'false') return false;
    return null;
  }

  if (['intentScore', 'icpScore'].includes(field)) {
    const n = Number(value);
    return Number.isFinite(n) ? n : null;
  }

  // id, companyId, icpTier -> plain string
  return String(value).trim();
}

function extractField(field, json, parsedJson, toonParsed) {
  const candidates = [
    json?.[field],
    parsedJson?.[field],
    json?.output?.[field],
    json?.data?.[field],
    toonParsed?.[field],
  ];
  for (const c of candidates) {
    if (c !== undefined && c !== null && c !== '') {
      return coerceValue(field, c);
    }
  }
  return null;
}

const results = [];

for (const item of $input.all()) {
  const json = item.json || {};

  const rawText =
    typeof json.output === 'string'
      ? json.output
      : typeof json.text === 'string'
      ? json.text
      : typeof json.toon === 'string'
      ? json.toon
      : null;

  const parsedJson = rawText ? extractJsonBlock(rawText) : null;
  const toonParsed = rawText && !parsedJson ? parseToonFields(rawText) : {};

  const extracted = {};
  for (const field of FIELDS) {
    extracted[field] = extractField(field, json, parsedJson, toonParsed);
  }

  // Twenty CRM's icpTier Select field only has A/B/C/D — fold A+ into A
  // Normalize ICP Tier to the exact TwentyCRM option value
if (extracted.icpTier) {
  const tier = String(extracted.icpTier).trim().toUpperCase();

  if (tier === 'A+' || tier === 'A_PLUS' || tier === 'A PLUS') {
    extracted.icpTier = 'A_PLUS';
  } else if (tier === 'A') {
    extracted.icpTier = 'A';
  } else if (tier === 'B') {
    extracted.icpTier = 'B';
  } else if (tier === 'C') {
    extracted.icpTier = 'C';
  } else if (tier === 'D') {
    extracted.icpTier = 'D';
  } else {
    extracted.icpTier = null;
  }
}

// If AI did not provide a tier, calculate it from ICP score
if (!extracted.icpTier && extracted.icpScore !== null) {
  const score = Number(extracted.icpScore);

  if (score >= 90) {
    extracted.icpTier = 'A_PLUS';
  } else if (score >= 80) {
    extracted.icpTier = 'A';
  } else if (score >= 70) {
    extracted.icpTier = 'B';
  } else if (score >= 50) {
    extracted.icpTier = 'C';
  } else {
    extracted.icpTier = 'D';
  }
}

  results.push({
    json: {
      ...json,
      ...extracted,
    },
  });
}

return results;

