// Get all input items
const items = $input.all();

// Helper function to map priority level to lead type
const mapPriorityToLeadType = (priorityLevel) => {
  const mapping = {
    'low': 'Cold',
    'medium': 'Warm',
    'high': 'Hot'
  };
  return mapping[priorityLevel?.toLowerCase()] || priorityLevel || '';
};

// Process each item
const results = items.map((item) => {
  // Get the output from AI Agent
  const aiResponse = item.json.output || item.json;
  // Parse JSON string if needed
  let parsedData;
  try {
    parsedData = typeof aiResponse === 'string' ? JSON.parse(aiResponse) : aiResponse;
  } catch (error) {
    // Return error object if parsing fails
    return {
      json: {
        email: '',
        error: 'Failed to parse AI response: ' + error.message
      }
    };
  }
  // Extract all fields for this item
  return {
    json: {
      email: parsedData.email || '',

      // BANT Evaluation
      bantEvaluation: {
        budgetScore: parsedData.bantEvaluation?.budgetScore || 0,
        authorityScore: parsedData.bantEvaluation?.authorityScore || 0,
        needScore: parsedData.bantEvaluation?.needScore || 0,
        timelineScore: parsedData.bantEvaluation?.timelineScore || 0,
        totalBantScore: parsedData.bantEvaluation?.totalBantScore || 0
      },

      // CHAMP Evaluation
      champEvaluation: {
        challengesScore: parsedData.champEvaluation?.challengesScore || 0,
        authorityScore: parsedData.champEvaluation?.authorityScore || 0,
        moneyScore: parsedData.champEvaluation?.moneyScore || 0,
        prioritizationScore: parsedData.champEvaluation?.prioritizationScore || 0,
        totalChampScore: parsedData.champEvaluation?.totalChampScore || 0
      },

      // Final Scores
      finalLeadScore: parsedData.finalLeadScore || 0,
      leadType: mapPriorityToLeadType(parsedData.priorityLevel),
      qualificationStatus: parsedData.qualificationStatus || '',
      leadReason: parsedData.leadReason || ''
    }
  };
});

// Return all results
return results;

