const normalize = (url) => String(url || '')
  .trim()
  .toLowerCase()
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/+$/, '');

const incomingItems = $input.all();
const teableItems = $('HTTP Request1').all();

const lookup = new Map();

// Build website → Teable Record ID lookup
for (const item of teableItems) {
  const records = item.json.records || [];

  for (const record of records) {
    const website = record.fields?.['Website'] || '';
    const normalizedWebsite = normalize(website);
    lookup.set(normalizedWebsite, record.id);
    console.log(`Teable: ${normalizedWebsite} → ${record.id}`);
  }
}

// Match incoming data to Teable IDs - Process ALL companies
const results = [];
for (const item of incomingItems) {
  const companies = item.json.data?.companies || [];

  // Loop through ALL companies (not just [0])
  for (let i = 0; i < companies.length; i++) {
    const company = companies[i];
    const website = company?.website?.primaryLinkUrl || '';
    const normalizedWebsite = normalize(website);
    const teableId = lookup.get(normalizedWebsite);

    console.log(`Incoming [${i}]: ${normalizedWebsite} → ${teableId || 'NOT FOUND'}`);

    results.push({
      json: {
        ...company,  // Each company separately
        teableId: teableId || null,
        recordExists: !!teableId
      }
    });
  }
}

return results;

